## STEP 2.4.5 OUTPUT
{
  "母图案概念": "以植物叶脉与年轮等自然脉络为骨架，叠加拓印质感、等高线式环形与细小标尺注释，形成山系户外感的轻量科学观察花型。",
  "核心元素锚点": {
    "固定不变的元素": [
      "叶脉骨架线稿",
      "年轮等高线环形",
      "半透明植物拓印",
      "细标尺注释符号"
    ],
    "允许变体的元素": [
      "叶片形态品类",
      "环形切片大小",
      "注释文字密度",
      "拓印虚实层次"
    ]
  },
  "母配色关系": {
    "主色_role": "60%，中低饱和植物绿、苔绿、橄榄灰至蓝灰绿，需与底色形成温和清晰对比",
    "辅色_role": "30%，低饱和米白、浅灰绿、雾蓝灰或浅卡其，作为半透明拓印与底纹层",
    "点缀色_role": "10%，较高明度奶油黄绿、淡湖蓝或柔和珊瑚橙，用于标尺、节点和微小注释"
  },
  "placement候选池": {
    "main": [
      {
        "位置": "左前大腿中部主面板",
        "档位": "A",
        "适合底色": "浅灰蓝、浅蓝、中蓝等冷调浅底色"
      },
      {
        "位置": "右前侧工装贴袋袋身中央区域",
        "档位": "B",
        "适合底色": "中灰、圣杯蓝、青冰灰等中性底色"
      },
      {
        "位置": "左外侧缝前后之间的大腿侧片",
        "档位": "C",
        "适合底色": "深蓝、牛油果绿等中深或偏户外底色"
      },
      {
        "位置": "后身右腿膝上主面板",
        "档位": "B",
        "适合底色": "淡卡其、珊瑚粉等暖调浅底色"
      },
      {
        "位置": "右前膝下至脚口上方主面板",
        "档位": "C",
        "适合底色": "浅蓝、中灰、青冰灰等低饱和底色"
      },
      {
        "位置": "左裤脚外侧脚口上方区域",
        "档位": "D",
        "适合底色": "所有底色，适合小型标尺叶脉点缀"
      }
    ]
  }
}
